install_and_verify_units(){ fail_stage services;[[ $EDUSCOPE_INSTALL_DRY_RUN == false ]]||{ action 'verify and enable units';return;};ln -sfn "$release_target" /opt/eduscope/current.new;mv -Tf /opt/eduscope/current.new /opt/eduscope/current;systemctl daemon-reload;udevadm control --reload;systemctl enable eduscope-helper.socket eduscope-runtime-config.service eduscope-pipeline-manager.service eduscope-core-api.service eduscope-stt.service eduscope-slide.service eduscope-question.service nginx.service;systemctl disable eduscope-kiosk.service eduscope-stunnel.service;systemctl --global enable eduscope-kiosk-browser.service; }
